B(y,t)[x:=s]=\begin{cases}
B(y,t)&y=x,\\
B(y,t[x:=s])&y\ne x\land y\notin FV_x(s),\\
B(z,(t[y:=var(z)])[x:=s])&y\ne x\land y\in FV_x(s),
\end{cases}
\quad z=fresh_x(Names_x(t)\cup Names_x(s)\cup\{x,y\}).

(\mu^\kappa Y.A)[X:=B]_X=\begin{cases}
\mu^\kappa Y.A&Y=X,\\
\mu^\kappa Y.(A[X:=B]_X)&Y\ne X\land Y\notin FTV(B),\\
\mu^\kappa Z.((A[Y:=tvar(Z)]_X)[X:=B]_X)&Y\ne X\land Y\in FTV(B),
\end{cases}
